          !options.force &&
          !options.dryRun
        ) {
          error("Batch delete requires --force flag");
          process.exit(EXIT_CODES.USAGE_ERROR);
        }

        const result = await executeBatchOperation({
          positionalRef: ref,
          refsFlag: options.refs,
          context: { ctx, tasks, items, index, options },
          items: tasks,
