  // AC: @multi-ref-batch ac-4 - Partial failure exit code
  if (!result.success) {
    if (result.summary.succeeded > 0) {
      // Partial failure
      process.exit(EXIT_CODES.ERROR);
    } else {
      // Complete failure
      process.exit(EXIT_CODES.ERROR);
    }
  }
}

