          return;
        }

        if (foundTask.status !== "pending") {
          error(errors.status.cannotStart(foundTask.status));
          process.exit(EXIT_CODES.VALIDATION_FAILED); // Exit code 4 = invalid state
        }

        // Update status
        const updatedTask: Task = {
          ...foundTask,
