    66→    const daemonConfig = context.manifest?.daemon;
    67→
    68→    // If daemon section missing entirely, auto_start defaults to true via schema
    69→    // Only skip if explicitly disabled
    70→    if (daemonConfig && daemonConfig.auto_start === false) {
    71→      return;
    72→    }
    73→
    74→    // Get port from config (schema defaults to 3456 if daemon section exists)
