    87→    const packageRoot = join(import.meta.dirname, '../../');
    88→    const daemonBinary = join(packageRoot, 'dist/daemon/index.js');
    89→    if (!existsSync(daemonBinary)) {
    90→      // Daemon not available, skip silently
    91→      return;
    92→    }
    93→
