    95→    // Set BUN_ENV=production to prevent Bun dev mode HTML transformation
    96→    const child = spawn(process.execPath, [daemonBinary, '--port', String(port), '--kspec-dir', kspecDir], {
    97→      detached: true,
    98→      stdio: 'ignore',
    99→      cwd: process.cwd(),
   100→      env: { ...process.env, BUN_ENV: 'production' },
   101→    });
