   152→registerTraitCommands(program);
   153→registerValidateCommand(program);
   154→registerHelpCommand(program);
   155→registerDeriveCommand(program);
   156→registerInboxCommands(program);
   157→registerShadowCommands(program);
   158→registerLogCommand(program);
   159→registerSearchCommand(program);
