          console.log(JSON.stringify(found, null, 2));
        } else {
          const idOrDomain =
            itemType === "agent"
              ? (found as Agent).id
              : itemType === "workflow"
                ? (found as Workflow).id
                : (found as Convention).domain;
          success(`Updated ${itemType}: ${idOrDomain}`);
