            // Save observation
            await saveObservation(ctx, observation);

            // Delete inbox item
            const deleted = await deleteInboxItem(ctx, item._ulid);
            if (!deleted) {
              error("Failed to delete inbox item after creating observation");
              process.exit(EXIT_CODES.ERROR);
            }

            await commitIfShadow(
