// AC: @trait-multi-ref-batch - Batch support for meta resolve
describe('Integration: meta resolve batch mode', () => {
  let tempDir: string;

  beforeEach(async () => {
    tempDir = await setupTempFixtures();
  });

  afterEach(async () => {
    await cleanupTempDir(tempDir);
  });

  // AC: @trait-multi-ref-batch ac-1 - --refs operates on all provided references
  it('should resolve multiple observations with --refs flag', () => {
    // Create multiple observations
    const obs1Output = kspec('meta observe friction "Friction 1"', tempDir);
    const obs1Match = obs1Output.match(/Created observation: ([A-Z0-9]{8})/);
    const obs1Ref = obs1Match![1];

    const obs2Output = kspec('meta observe success "Success 1"', tempDir);
    const obs2Match = obs2Output.match(/Created observation: ([A-Z0-9]{8})/);
    const obs2Ref = obs2Match![1];

    const obs3Output = kspec('meta observe question "Question 1"', tempDir);
    const obs3Match = obs3Output.match(/Created observation: ([A-Z0-9]{8})/);
    const obs3Ref = obs3Match![1];

    // Resolve all three with --refs and shared resolution text
    const output = kspec(
      `meta resolve --refs @${obs1Ref} @${obs2Ref} @${obs3Ref} --resolution "Batch resolved"`,
      tempDir
    );

    // Should show summary
    expect(output).toContain('3 of 3');

    // Verify all are resolved
    const observations = kspecJson<any[]>('meta observations --all', tempDir);
    const resolved = observations.filter(
      (o) => o._ulid.startsWith(obs1Ref) || o._ulid.startsWith(obs2Ref) || o._ulid.startsWith(obs3Ref)
    );
    expect(resolved.every((o) => o.resolved)).toBe(true);
  });

  // AC: @trait-multi-ref-batch ac-2 - Continue processing after errors
  it('should continue processing when some refs fail', () => {
    // Create two observations, resolve one
    const obs1Output = kspec('meta observe friction "Can resolve"', tempDir);
    const obs1Match = obs1Output.match(/Created observation: ([A-Z0-9]{8})/);
    const obs1Ref = obs1Match![1];

    const obs2Output = kspec('meta observe friction "Already done"', tempDir);
    const obs2Match = obs2Output.match(/Created observation: ([A-Z0-9]{8})/);
    const obs2Ref = obs2Match![1];

    // Resolve obs2 first
    kspec(`meta resolve @${obs2Ref} "Pre-resolved"`, tempDir);

    // Try to resolve both - obs2 should fail (already resolved)
    try {
      const output = kspec(
        `meta resolve --refs @${obs1Ref} @${obs2Ref} --resolution "Batch resolve"`,
        tempDir
      );
      // Should show partial success
      expect(output).toContain('1 of 2');
    } catch (e: any) {
      // Partial failure still exits with error code but shows partial success
      expect(e.message).toContain('1 of 2');
    }

    // Obs1 should be resolved despite obs2 failing
    const observations = kspecJson<any[]>('meta observations --all', tempDir);
    const obs1 = observations.find((o) => o._ulid.startsWith(obs1Ref));
    expect(obs1?.resolved).toBe(true);
  });

  // AC: @trait-multi-ref-batch ac-3 - Exit code 0 when all succeed
  it('should exit with code 0 when all refs succeed', () => {
    // Create observations
    const obs1Output = kspec('meta observe friction "Resolve me 1"', tempDir);
    const obs1Match = obs1Output.match(/Created observation: ([A-Z0-9]{8})/);
    const obs1Ref = obs1Match![1];

    const obs2Output = kspec('meta observe friction "Resolve me 2"', tempDir);
    const obs2Match = obs2Output.match(/Created observation: ([A-Z0-9]{8})/);
    const obs2Ref = obs2Match![1];

    // Should not throw (exit code 0)
    const output = kspec(
      `meta resolve --refs @${obs1Ref} @${obs2Ref} --resolution "All good"`,
      tempDir
    );
    expect(output).toContain('2 of 2');
  });

  // AC: @trait-multi-ref-batch ac-4 - Exit code 1 when any fail
  it('should exit with code 1 when any refs fail', () => {
    const obsOutput = kspec('meta observe friction "Will fail"', tempDir);
    const obsMatch = obsOutput.match(/Created observation: ([A-Z0-9]{8})/);
    const obsRef = obsMatch![1];

    // Resolve it first
    kspec(`meta resolve @${obsRef} "Already done"`, tempDir);

    // Try to resolve again - should fail with exit code 1
    try {
      kspec(`meta resolve --refs @${obsRef} --resolution "Should fail"`, tempDir);
      expect.fail('Should have thrown due to exit code 1');
    } catch (e: any) {
      expect(e.message).toContain('Already resolved');
    }
  });

  // AC: @trait-multi-ref-batch ac-5 - Success and failure counts reported
  it('should report success and failure counts', () => {
    // Create 3 observations, pre-resolve 1
