        `meta resolve @${obsRef} --refs @${obsRef} --resolution "Both"`,
        tempDir
      );
      expect.fail('Should have thrown error');
    } catch (e: any) {
      expect(e.message).toContain('Cannot use both positional ref and --refs');
    }
