node -e "
const {kspec, setupTempFixtures, cleanupTempDir, kspecJson} = require('./dist/tests-commonjs-compat/cli.js');

async function test() {
  const tempDir = await setupTempFixtures();
  console.log('Temp dir:', tempDir);

  // Create observations
  const obs1 = kspec('meta observe friction \"Test1\"', tempDir);
  console.log('Obs1:', obs1.stdout);

  const obs2 = kspec('meta observe friction \"Test2\"', tempDir);
  console.log('Obs2:', obs2.stdout);

  // Try batch resolve
  const m1 = obs1.stdout.match(/([A-Z0-9]{8})/);
  const m2 = obs2.stdout.match(/([A-Z0-9]{8})/);

  if (m1 && m2) {
    const ref1 = m1[1];
    const ref2 = m2[1];
    console.log('Refs:', ref1, ref2);

    const cmd = \`meta resolve --refs @\${ref1} @\${ref2} --resolution \"BatchTest\" --json\`;
    console.log('Command:', cmd);

    try {
      const result = kspec(cmd, tempDir, { expectFail: true });
      console.log('Exit code:', result.exitCode);
      console.log('Stdout:', result.stdout);
      console.log('Stderr:', result.stderr);
    } catch (e) {
      console.log('Error:', e.message);
    }
  }

  await cleanupTempDir(tempDir);
}

test();
" 2>&1

