    const conventionsFile = path.join(metaDir, 'conventions.yaml');
    await fs.writeFile(
      conventionsFile,
      `conventions:
  - _ulid: 01KF8850000000000000000010
    domain: testing-include
    rules:
      - Write tests for included items
