        const { getDiffSince } = await import("../../utils/index.js");

        // Gather review context
        const reviewContext: {
          task: typeof foundTask;
          spec: LoadedSpecItem | null;
          diff: string | null;
          started_at: string | null;
          testCoverage?: { covered: string[]; uncovered: string[] };
        } = {
          task: foundTask,
