            executeOperation: async (task: LoadedTask, context) => {
              return await setTaskFields(
                task,
                context.ctx,
                context.tasks,
                context.items,
                context.allMetaItems,
                context.index,
                context.options,
              );
            },
            getUlid: (task: LoadedTask) => task._ulid,
