                success: true,
                message: `Completed task: ${index.shortUlid(updatedTask._ulid)}`,
                data: updatedTask,
                ...(forcingBlockedTask && { warning: warningMsg }),
              };
            } catch (err) {
              return {
                success: false,
                error: err instanceof Error ? err.message : String(err),
              };
            }
          },
          getUlid: (task) => task._ulid,
        });

