        if (!options.type || options.type === "workflow") {
          for (const workflow of metaCtx.workflows || []) {
            items.push({
              id: workflow.id,
              type: "workflow",
              context: workflow.trigger,
              ulid: workflow._ulid,
            });
          }
        }

        // Add conventions
        if (!options.type || options.type === "convention") {
          for (const convention of metaCtx.conventions || []) {
            items.push({
